<?php
require_once __DIR__ . '/../app/bootstrap.php'; require_login();
$user = current_user(); $pdo = db();
if ($user['role'] === 'system_admin') {
    $coops = (int)$pdo->query('SELECT COUNT(*) FROM cooperatives')->fetchColumn();
    $members = (int)$pdo->query('SELECT COUNT(*) FROM members')->fetchColumn();
    $active = (int)$pdo->query("SELECT COUNT(*) FROM members WHERE status='active'")->fetchColumn();
    $recent = $pdo->query('SELECT m.member_number, m.first_name, m.last_name, m.status, m.joined_on, c.name AS cooperative_name FROM members m JOIN cooperatives c ON c.id=m.cooperative_id ORDER BY m.created_at DESC LIMIT 6')->fetchAll();
} else {
    $cid = (int)($user['cooperative_id'] ?? 0);
    $s=$pdo->prepare('SELECT COUNT(*) FROM members WHERE cooperative_id=?'); $s->execute([$cid]); $members=(int)$s->fetchColumn();
    $s=$pdo->prepare("SELECT COUNT(*) FROM members WHERE cooperative_id=? AND status='active'"); $s->execute([$cid]); $active=(int)$s->fetchColumn();
    $coops = $cid ? 1 : 0;
    $s=$pdo->prepare('SELECT m.member_number,m.first_name,m.last_name,m.status,m.joined_on,c.name AS cooperative_name FROM members m JOIN cooperatives c ON c.id=m.cooperative_id WHERE m.cooperative_id=? ORDER BY m.created_at DESC LIMIT 6'); $s->execute([$cid]); $recent=$s->fetchAll();
}
$pageTitle='Dashboard'; require __DIR__.'/includes/header.php';
?><div class="welcome-row"><div><h2>Good <?= (int)date('G') < 12 ? 'morning' : ((int)date('G') < 17 ? 'afternoon' : 'evening') ?>, <?= e(explode(' ',$user['full_name'])[0]) ?>.</h2><p class="muted">Here is the latest overview of your cooperative workspace.</p></div><a class="btn primary" href="member-form.php">＋ Add member</a></div><div class="stats-grid"><article class="stat-card"><div class="stat-top"><span class="stat-icon purple">⌂</span><span class="stat-label">COOPERATIVES</span></div><div class="stat-value"><?= number_format($coops) ?></div><div class="stat-foot">Registered organizations</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon blue">♙</span><span class="stat-label">TOTAL MEMBERS</span></div><div class="stat-value"><?= number_format($members) ?></div><div class="stat-foot">Member records in your scope</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon green">✓</span><span class="stat-label">ACTIVE MEMBERS</span></div><div class="stat-value"><?= number_format($active) ?></div><div class="stat-foot"><?= $members ? number_format(($active/$members)*100,1).'%' : '0%' ?> of recorded members</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon amber">◷</span><span class="stat-label">TODAY</span></div><div class="stat-value date-value"><?= date('d M') ?></div><div class="stat-foot"><?= date('l, Y') ?></div></article></div><section class="panel"><div class="panel-heading"><div><h3>Recently added members</h3><p class="muted">The latest records in your workspace</p></div><a class="text-link" href="members.php">View all members →</a></div><?php if (!$recent): ?><div class="empty-state"><div class="empty-icon">♙</div><h3>No members yet</h3><p>Add the first member to start building your cooperative records.</p><a class="btn primary" href="member-form.php">Add first member</a></div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Member</th><th>Member number</th><th>Cooperative</th><th>Joined</th><th>Status</th></tr></thead><tbody><?php foreach($recent as $m): ?><tr><td><div class="person-cell"><span class="avatar small"><?= e(strtoupper(substr($m['first_name'],0,1).substr($m['last_name'],0,1))) ?></span><span><strong><?= e($m['first_name'].' '.$m['last_name']) ?></strong><small>Member</small></span></div></td><td><?= e($m['member_number']) ?></td><td><?= e($m['cooperative_name']) ?></td><td><?= e($m['joined_on']) ?></td><td><span class="badge <?= e($m['status']) ?>"><?= e(ucfirst($m['status'])) ?></span></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php require __DIR__.'/includes/footer.php'; ?>
